package ro.leo.visual;
import android.content.*;import android.os.Bundle;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
public final class WallpaperActivity extends LeoActivity {
    private int stock=-1,themePreview=-1;
    protected void onCreate(Bundle state){super.onCreate(state);show();}
    private void show(){stock=-1;themePreview=-1;ArrayList<String> values=new ArrayList<String>(Arrays.asList(Appearance.THEMES));values.add("Fundaluri incluse · 4 modele");values.add("Imagine din Galerie");values.add("Elimină imaginea de fundal");list("Fundaluri și teme",values,0,new Choice(){public void pick(int i){if(i<Appearance.THEMES.length){previewTheme(i);}else if(i==Appearance.THEMES.length)preview(0);else if(i==Appearance.THEMES.length+1)startActivity(new Intent(WallpaperActivity.this,GalleryActivity.class).putExtra("wallpaper",true));else options("Elimini fundalul?",new String[]{"Păstrează","Elimină"},new Choice(){public void pick(int yes){if(yes==1){if(Appearance.wallpaper(WallpaperActivity.this).exists()&&!Appearance.wallpaper(WallpaperActivity.this).delete())notice("Nu poate fi eliminat");else notice("Fundal eliminat");}}});}},"",null);}
    private void preview(int which){stock=Math.floorMod(which,StockWallpapers.NAMES.length);begin(StockWallpapers.NAMES[stock]);root.addView(new View(this){protected void onDraw(Canvas c){StockWallpapers.draw(c,stock,getWidth(),getHeight());}},new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){try{StockWallpapers.apply(WallpaperActivity.this,stock);notice("Fundal aplicat pe Home și ecranul blocat");}catch(java.io.IOException e){notice("Fundalul nu a putut fi salvat");}}};back=new Runnable(){public void run(){show();}};footer("Aplică","← / → model","Înapoi");}
    private void previewTheme(int which){stock=-1;themePreview=Math.floorMod(which,Appearance.THEMES.length);begin("Previzualizare temă");final Appearance.Palette sample=new Appearance.Palette(Appearance.COLORS[themePreview]);root.addView(new View(this){final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/218f);p.setShader(new LinearGradient(0,0,240,218,sample.gradient,null,Shader.TileMode.CLAMP));c.drawRect(0,0,240,218,p);p.setShader(null);p.setColor(sample.bar);c.drawRoundRect(12,12,228,62,8,8,p);p.setColor(Color.WHITE);p.setTextSize(18);c.drawText(Appearance.THEMES[themePreview],22,43,p);p.setColor(sample.card);c.drawRoundRect(12,77,228,119,8,8,p);p.setColor(Color.WHITE);p.setTextSize(16);c.drawText("Mesaje · Contacte",23,104,p);p.setColor(sample.selection);c.drawRoundRect(12,130,228,174,8,8,p);p.setColor(sample.ink);c.drawText("Selecție din taste",23,158,p);p.setColor(sample.bar);c.drawRect(0,187,240,218,p);p.setColor(Color.WHITE);p.setTextSize(12);c.drawText("← / → alte teme · OK aplică",23,202,p);c.restore();}},new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){getSharedPreferences("appearance",0).edit().putInt("theme",themePreview).putBoolean("warm",themePreview==1).apply();show();notice("Tema aplicată");}};back=new Runnable(){public void run(){show();}};footer("Aplică","← / → temă","Anulează");}
    public boolean onKeyDown(int key,KeyEvent e){if(themePreview>=0){if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){previewTheme(themePreview+(key==KeyEvent.KEYCODE_DPAD_LEFT?-1:1));return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getRepeatCount()==0)left.run();return true;}}if(stock>=0){if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){preview(stock+(key==KeyEvent.KEYCODE_DPAD_LEFT?-1:1));return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getRepeatCount()==0&&left!=null)left.run();return true;}}return super.onKeyDown(key,e);}
}
